import React from 'react';
import TrackSearch from '../components/TrackSearch';
import { useNavigate } from 'react-router-dom';

const Home = () => {
  const navigate = useNavigate();

  const handleTrackSelected = (track) => {
    // Navigate to the SimilarTracks page with selected track info
    navigate(`/similar-tracks?track=${encodeURIComponent(track.name)}`);
  };

  return (
    <div>
      <h2>Find Similar Tracks</h2>
      <TrackSearch onTrackSelected={handleTrackSelected} />
    </div>
  );
};

export default Home;
